func validateAttachment(attachment string) error {
	if attachment == "" {
		return nil
	}

	bytes := []byte(attachment)
	if !json.Valid(bytes) {
		return errors.InvalidFieldError("attachment", "must be a json string")
	}

	if len(bytes) > maxVariantAttachmentSize {
		return errors.InvalidFieldError("attachment",
			fmt.Sprintf("must be less than %d KB", maxVariantAttachmentSize),
		)
	}
	return nil
}

func validateArrayValue(property, value string, comparisonType ComparisonType) error {
	var typeName string
	switch comparisonType {
	case ComparisonType_STRING_COMPARISON_TYPE:
		typeName = "string"
	case ComparisonType_NUMBER_COMPARISON_TYPE:
		typeName = "number"
	default:
		return errors.ErrInvalidf("invalid constraint type: %q", comparisonType.String())
	}

	invalidValue := func() error {
		return errors.ErrInvalidf("invalid value provided for property %q of type %s", property, typeName)
	}

	var items []json.RawMessage
	if err := json.Unmarshal([]byte(value), &items); err != nil || items == nil {
		return invalidValue()
	}

	for _, item := range items {
		if strings.TrimSpace(string(item)) == "null" {
			return invalidValue()
		}
	}

	switch comparisonType {
	case ComparisonType_STRING_COMPARISON_TYPE:
		var values []string
		if err := json.Unmarshal([]byte(value), &values); err != nil {
			return invalidValue()
		}
	case ComparisonType_NUMBER_COMPARISON_TYPE:
		var values []float64
		if err := json.Unmarshal([]byte(value), &values); err != nil {
			return invalidValue()
		}
	}

	if len(items) > MAX_JSON_ARRAY_ITEMS {
		return errors.ErrInvalidf("too many values provided for property %q of type %s (maximum %d)", property, typeName, MAX_JSON_ARRAY_ITEMS)
	}

